                ),
            )
        )
        samples = SamplingBudget(one_hot="all", sparse=8, dense=self.int_range(8, 40), sparse_max_weight=2)
        # Schedule beamwidth: narrow (2) for early/mid bands, wider (8) for terminal tail
        # rank≤130 triggers the wider beam in the terminal dim 1-4 region
        self.set_action_selection(
            ranks=[130, 0],
            values=[
                ActionSelection(beamwidth=2, mode="softmax", temperature=0.16),
                ActionSelection(beamwidth=8, mode="softmax", temperature=0.16),
            ],
        )
        self.set_action_pool(ActionPool(final_size=self.int_range(24, 48)))
        self.set_tohpe_search(TohpeSearch(samples, SourcePool(keep=6, reserve=1), z_choices=4))
        # Increased min_buckets to 32 for better z coverage in terminal dims; removed hard
        # limit_bucket and max_buckets caps to avoid truncating rare-positive z research
        self.set_todd_search(
            ToddSearch(
                SamplingBudget(one_hot=1, sparse=0, dense=0, sparse_max_weight=2),
                SourcePool(keep=self.int_range(6, 12), reserve=2),
                actions_per_bucket=4,
                buckets=ZBucketSearch(min_buckets=32, max_buckets=-1, limit_bucket=-1),
            )
        )

    def __call__(self, params: Iterable[float]) -> float:
        values = np.asarray(self.run(params, SEEDS), dtype=float)
        return float(values.min() + 0.02 * values.std())


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        n = len(evaluator.extract_active())
        super().__init__(n_var=n, n_obj=1, xl=np.full(n, -1.5), xu=np.full(n, 1.5))
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def entrypoint():
    # Mid-margin regime: margin=36 ≈ 1/4 to 3/4 of (168-123)=45 range, branching at
    # rank ~136 to build a distinct descent rather than replaying the tail
    evaluator = Evaluator(path_name="f123_i168_d6aa805f_z198of2446", margin=36, max_depth=500)
    algorithm = DE(pop_size=32, variant="DE/rand/1/bin", CR=0.9, F=0.6)
    minimize(Problem(evaluator), algorithm, termination=("n_eval", N_EVAL), seed=17, verbose=False)
    return evaluator.get_best()
